#ifndef MEDIA_AAC_TABLES_H
#define MEDIA_AAC_TABLES_H

#include <stdint.h>

// Constant tables of AAC-LC (generated by tools/gen_aac_tables.py).

struct aac_hcb {
    int nvals;                  // values per codeword: 4 (codebooks 1-4) or 2 (5-11)
    int mod;                    // each value is one base-`mod` digit of the codeword index
    int off;                    // value = digit - off
    int count;                  // number of codewords (mod ^ nvals)
    const uint8_t* len;         // [index] code length in bits
    const uint16_t* code;       // [index] the code, right aligned
};

extern const struct aac_hcb aac_hcb[11];        // codebook n is aac_hcb[n - 1]
extern const uint8_t aac_sf_len[121];           // scalefactor codebook, indexed by delta + 60
extern const uint32_t aac_sf_code[121];

extern const int aac_sample_rates[13];
extern const uint8_t aac_num_swb_long[12];      // by sampling_frequency_index
extern const uint8_t aac_num_swb_short[12];
extern const uint8_t aac_tns_max_long[12];
extern const uint8_t aac_tns_max_short[12];
extern const uint16_t aac_swb_long[12][52];     // band offsets, num_swb + 1 entries
extern const uint16_t aac_swb_short[12][16];

#endif
